"""Exact finite management programs used for the original local Git proof.

No execution on import. Caller supplies private pins, journal and finite budgets.
These programs neither launch a model nor adopt a runtime binding.
"""

COMMON = '\nimport base64,contextlib,hashlib,io,json,os,stat,subprocess,sys,time,types,zlib\nfrom pathlib import Path\nassert os.getuid()==2009 and os.uname().nodename==\'corelab-4080s\'and not os.environ.get(\'PBS_JOBID\')\nsha=lambda b:hashlib.sha256(b).hexdigest();raw=lambda v:(json.dumps(v,indent=2,allow_nan=False)+\'\\n\').encode()\nroot=Path(P[\'root\']);mb=(root/\'RUN_MANIFEST.json\').read_bytes();assert sha(mb)==P[\'manifest\']\nm=json.loads(mb);cfgb=(root/\'EXECUTION_CONFIG.private.json\').read_bytes();assert sha(cfgb)==m[\'execution\'][\'configuration_sha256\'];cfg=json.loads(cfgb)\nlb=Path(cfg[\'canonical_LOCAL_ledger\']).read_bytes();assert sha(lb)==P[\'LOCAL_sha256\'];local=json.loads(lb)\nrow=local[\'V5_CD_Core_allocations\'][P[\'request_id\']];assert row[\'status\']==\'PRESTART_INTENT_UNKNOWN_NO_RETRY\'and row[\'native_handle\']is None and row[\'request_sha256\']==P[\'request_sha256\']\nassert local[\'pending_queries\']==local[\'pending_updates\']==local[\'unknown_effects\']==[]\nbinding=json.loads((root/\'OUTPUT_BINDING.private.json\').read_bytes());lease=json.loads(Path(binding[\'lease\']).read_bytes())\nassert lease[\'status\']==\'ACTIVE\'and lease[\'run_uuid\']==root.name and time.time()<lease[\'deadline_epoch\']\nunits={}\nfor unit in P[\'units\']:\n q=subprocess.run([\'systemctl\',\'--user\',\'show\',unit,\'-p\',\'MainPID\',\'-p\',\'LoadState\'],capture_output=True,text=True,timeout=3)\n props=dict(x.split(\'=\',1)for x in q.stdout.splitlines()if \'=\'in x);assert props==dict(MainPID=\'0\',LoadState=\'not-found\');units[unit]=props\nassert not(root/\'resident\').exists()\ndestination=root/\'cold-inputs-20261030\';sb=(destination/\'STAGE_RESULT.json\').read_bytes();assert sha(sb)==P[\'original_stage_result_sha256\'];stage=json.loads(sb)\nfor name,pin in stage[\'files\'].items():\n p=destination/name;s=p.lstat();assert stat.S_ISREG(s.st_mode)and s.st_uid==2009 and not s.st_mode&0o222\n b=p.read_bytes();assert len(b)==pin[\'bytes\']and sha(b)==pin[\'sha256\']\nsource=destination/\'official\';code=Path(cfg[\'source_code\'])\nassert sha(json.dumps(P[\'frozen\'],sort_keys=True).encode())==\'7666e26ed616dc9facc93fc5b5ac554ab737ba99f1f3e6c2c9887bf5dd207f9b\'\nassert all(sha((code/name).read_bytes())==pin for name,pin in P[\'frozen\'].items())\ndef native_official_check():\n body="import hashlib,json,sys;from pathlib import Path;sys.path[:0]="+repr([str(code),str(code/\'src\')])+";from scripts.pi0292.train_adapter import official_import;official_import("+repr(str(source))+");assert \'torch\'not in sys.modules;print(json.dumps(dict(status=\'ORIGINAL_FROZEN_OFFICIAL_IMPORT_ALL_GIT_CHECKS_PASS\',original_adapter_sha256=hashlib.sha256(Path(official_import.__code__.co_filename).read_bytes()).hexdigest(),model_loads=0,queries=0,physics=0)))"\n env=dict(os.environ,CUDA_VISIBLE_DEVICES=\'\',PYTHONDONTWRITEBYTECODE=\'1\',OMP_NUM_THREADS=\'1\',OPENBLAS_NUM_THREADS=\'1\',MKL_NUM_THREADS=\'1\')\n q=subprocess.run([P[\'runtime_python\'],\'-B\',\'-c\',body],cwd=source,env=env,capture_output=True,text=True,timeout=12)\n assert q.returncode==0,(q.returncode,q.stderr[:1000]);v=json.loads(q.stdout);assert v[\'original_adapter_sha256\']==P[\'frozen\'][\'scripts/pi0292/train_adapter.py\'];return v\n'

